+    padding: 0.2rem 0.4rem;
+    border-radius: 3px;
+    transition: background 0.1s, color 0.1s;
+}
+
+::deep .close-btn:hover {
+    background: #404249;
+    color: #f2f3f5;
+}
+
+::deep .thread-root-message {
+    padding: 0.75rem 1rem;
+    border-bottom: 1px solid #1e1f22;
+    background: #232428;
+    flex-shrink: 0;
+}
+
+::deep .thread-root-message p {
+    margin: 0.25rem 0 0;
+    font-size: 0.85rem;
+    color: #dbdee1;
+}
+
+::deep .thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 0.75rem 1rem;
+    display: flex;
+    flex-direction: column;
+    gap: 0.5rem;
+}
+
+::deep .thread-reply {
+    padding: 0.4rem 0;
+}
